const resposta = String($input.first().json.Mensagem ?? '');

// Se for um orçamento, não quebra em partes.
const ehOrcamento = /📄|ORÇAMENTO/i.test(resposta);

if (ehOrcamento) {
  return {
    json: {
      respostas: [resposta.trim()]
    }
  };
}

// Abreviações que terminam com ponto e não devem ser tratadas como fim de frase.
const abreviacoes = ["Dr.", "Sr.", "Sra.", "Dra.", "Prof.", "Srta.", "1.", "2.", "3.", "4.", "5.", "6.", "7."];

function eAbreviacao(palavra) {
  return abreviacoes.includes(palavra);
}

function dividirResposta(texto) {
  const partes = texto.split(/(?<=[.!?])\s(?![\uD800-\uDFFF])/);

  let resultado = [];
  for (let i = 0; i < partes.length; i++) {
    const parte = partes[i].trim();

    if (i > 0) {
      const palavras = partes[i - 1].split(" ");
      const ultimaPalavra = palavras[palavras.length - 1].trim();

      if (eAbreviacao(ultimaPalavra)) {
        resultado[resultado.length - 1] += " " + parte;
        continue;
      }
    }

    resultado.push(parte);
  }

  return resultado.filter(parte => parte.length > 0);
}

const partesDivididas = dividirResposta(resposta);

return {
  json: {
    respostas: partesDivididas
  }
};
